CREATE OR REPLACE FUNCTION public.claim_ebook_gift(_token text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_uid uuid:=auth.uid(); v_gift public.ebook_gifts; v_ent_id uuid; v_email text; v_meta jsonb; BEGIN IF v_uid IS NULL THEN RAISE EXCEPTION 'Giriş yapmalısınız'; END IF; v_email:=lower(auth.jwt()->>'email'); IF v_email IS NULL OR NOT EXISTS (SELECT 1 FROM auth.users WHERE id=v_uid AND email_confirmed_at IS NOT NULL) THEN RAISE EXCEPTION 'E-posta adresinizi onaylayın'; END IF; SELECT * INTO v_gift FROM public.ebook_gifts WHERE claim_token=_token FOR UPDATE; IF v_gift.id IS NULL THEN RAISE EXCEPTION 'Geçersiz bağlantı'; END IF; IF lower(v_gift.recipient_email)<>v_email THEN RAISE EXCEPTION 'Bu hediyeyi almak için alıcı e-posta adresiyle giriş yapın'; END IF; IF v_gift.status='claimed' THEN IF v_gift.claimed_by_user_id=v_uid THEN SELECT id INTO v_ent_id FROM public.user_entitlements WHERE user_id=v_uid AND type='ebook' AND metadata->>'gift_id'=v_gift.id::text LIMIT 1; RETURN v_ent_id; END IF; RAISE EXCEPTION 'Bu hediye zaten kullanılmış'; END IF; v_meta:=jsonb_build_object('product_slug',v_gift.product_slug,'recipient_name',v_gift.recipient_name,'recipient_email',v_gift.recipient_email,'is_gift',true,'gift_id',v_gift.id,'gift_from',v_gift.buyer_user_id,'gift_note',COALESCE(v_gift.gift_note,'')); INSERT INTO public.user_entitlements(user_id,type,source_order_id,metadata) VALUES(v_uid,'ebook',v_gift.order_id,v_meta) RETURNING id INTO v_ent_id; UPDATE public.ebook_gifts SET status='claimed',claimed_by_user_id=v_uid,claimed_at=now() WHERE id=v_gift.id; RETURN v_ent_id; END $$; REVOKE ALL ON FUNCTION public.claim_ebook_gift(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.claim_ebook_gift(text) TO authenticated,service_role;